package com.taller.portal.controller;
import com.taller.portal.dto.AuthDtos.*; import com.taller.portal.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService s;public AuthController(AuthService s){this.s=s;}@PostMapping("/login")public AuthResponse login(@Valid @RequestBody Login v){return s.login(v);}@PostMapping("/register")public AuthResponse register(@Valid @RequestBody Register v){return s.register(v);}@PostMapping("/recover")@ResponseStatus(HttpStatus.NO_CONTENT)public void recover(@Valid @RequestBody Recovery v){s.recover(v);}@ExceptionHandler({IllegalArgumentException.class}) ResponseEntity<Map<String,String>> err(Exception e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}
